'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),{EventEmitter}=require('node:events'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');const {createLobby}=require('../lobby.cjs');
class Socket extends EventEmitter{constructor(){super();this.readyState=1;this.bufferedAmount=0;this.messages=[];}send(s){let m=JSON.parse(s);this.messages.push(m);this.receive?.(m);}post(m){this.emit('message',Buffer.from(JSON.stringify(m)));}close(){this.readyState=3;this.emit('close');}}
test('Room codes, two-player limit, role enforcement, sanitized input, cleanup',()=>{let lobby=createLobby(),h=new Socket(),g=new Socket(),third=new Socket();for(let s of [h,g,third])lobby.attach(s);h.post({type:'create'});let code=h.messages[0].code;assert.match(code,/^[A-Z2-9]{6}$/);g.post({type:'join',code});assert.equal(h.messages.at(-1).type,'peer-ready');third.post({type:'join',code});assert.equal(third.messages.at(-1).type,'error');let before=h.messages.length;g.post({type:'snapshot',state:{cheat:true}});assert.equal(h.messages.length,before);g.post({type:'input',keys:['w','d','evil','w'],aim:99});assert.deepEqual(h.messages.at(-1),{type:'input',keys:['w','d'],aim:2});h.post({type:'snapshot',state:{test:1}});assert.equal(g.messages.at(-1).state.test,1);g.close();assert.equal(lobby.rooms.size,0);assert.equal(lobby.members.size,0);assert.equal(h.messages.at(-1).type,'peer-left');});
function game(socket,storage=new Map()){let time=0,els={},listeners={};const no=()=>{},ctx=new Proxy({},{get:()=>no,set:()=>true});function el(){return{dataset:{},children:[],hidden:false,tagName:'DIV',value:'',textContent:'',clientWidth:700,clientHeight:420,addEventListener:no,setAttribute:no,focus:no,click(){this.onclick?.()},getContext:()=>ctx,replaceChildren(){this.children=[]},append(...a){this.children.push(...a)}}}const net={role:'solo',code:'',send:m=>socket.post(m),onEvent:no,connect(type,code,characterId){socket.post({type,code,characterId})},leave(){this.role='solo';this.code='';socket.post({type:'leave'})}};socket.receive=m=>{if(m.type==='created'){net.role='host';net.code=m.code}if(m.type==='joined'){net.role='guest';net.code=m.code}net.onEvent(m)};const box={console,Math,Set,document:{getElementById:id=>els[id]||=el(),createElement:el,documentElement:{dataset:{}},addEventListener:no},window:{Coop:net,addEventListener:(name,fn)=>listeners[name]=fn},localStorage:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v)},ResizeObserver:class{observe(){}},devicePixelRatio:1,requestAnimationFrame:no,performance:{now:()=>time},getComputedStyle:()=>({getPropertyValue:()=> '#009de0'})};let src=fs.readFileSync(path.join(__dirname,'../public/game.js'),'utf8').replace('})();',`globalThis.t={roomKey,guestStep,makeNetworkSnapshot,applyNetworkSnapshot,smoothPosition,recordMark,renderMarks,bossUpdate,hazardsStep,hazardCircle,hazardBeam,descend,goFloor:n=>{floor=n;generateFloor();enterRoom(rooms.find(r=>r.kind==='boss').id)},feedbackStep,drawFeedback,updateCamera,directionTargets,generateFloor,neighbors,moveBody,coverHit,worldLoot,unlockEntrance,spawnLoot,spawnBoss,spawnEnemies,regularBossTypes,isMajorBoss,maxLives,shotDamage,shotRate,stepSpeed,useAbility,abilityStep,hitEnemy,take,items,dealItems,newItems,rarityWeights,rarityPrices,offers,steerShot,specialStatusStep,shoot,gear,canEquip,pickupItems,newRun,frame,enterRoom,makeSnapshot,applySnapshot,damagePlayer,damagePartner,roomCleared,keys,get:()=>({W,H,VIEW_W,VIEW_H,camera,combatTexts,pendingInputs,remoteAck,remoteCommands,gridSize,startRoom,keyCount,player,partner,state,rooms,current,shots,coins,maxHP,build,boss,coopActive,hazards,bullets,enemies,runMilestones,completionMarks}),setCoins:n=>coins=n,setKeys:n=>keyCount=n,unprotect:()=>{inv=0;remoteInv=0},downHost:()=>{player.hp=1;inv=0;damagePlayer()},downPartner:()=>{partner.hp=1;remoteInv=0;damagePartner()},wipe:()=>{enemies.forEach(e=>e.dead=true);if(boss)boss.dead=true},pickPartner:()=>{let r=rooms[current],p=r.loot[0];partner.x=p.nx*W;partner.y=p.ny*H;pickupDelay=0},setInputAge:()=>remoteAt=performance.now(),clearKeys:()=>keys.clear()};})();`);vm.createContext(box);vm.runInContext(src,box);return{...box.t,net,els,key:k=>listeners.keydown({key:k,repeat:false,target:{},preventDefault:no}),blur:()=>listeners.blur(),tick(n=1){for(let i=0;i<n;i++){time+=20;box.t.frame(time)}}};}
test('Two simulated clients: host/guest synchronization, independent control, shots, pickups, revives and defeat',()=>{let lobby=createLobby({now:()=>1}),hs=new Socket(),gs=new Socket();lobby.attach(hs);lobby.attach(gs);const h=game(hs),g=game(gs);hs.post({type:'create'});gs.post({type:'join',code:h.net.code});h.tick(5);assert.equal(g.get().state,'play');assert.equal(h.get().partner.hp,3);let px=h.get().player.x,remoteX=h.get().partner.x;g.keys.add('d');for(let n=0;n<8;n++){g.tick();h.tick()}assert(h.get().partner.x>remoteX);assert.equal(h.get().player.x,px);h.tick(5);assert(Math.abs(g.get().partner.x-h.get().partner.x)<=20,'guest follows within one snapshot interval');g.clearKeys();g.keys.add('arrowup');for(let n=0;n<6;n++){g.tick();h.tick()}assert(h.get().shots.length>0);assert.equal(g.get().current,h.get().current);
let treasure=h.get().rooms.find(r=>r.kind==='treasure');h.enterRoom(treasure.id);h.pickPartner();h.tick();assert.equal(h.get().build.length,0,'guest pickup does not enter host inventory');assert.equal(h.get().partner.inventory.build.length,1,'guest owns the collected recipe');assert(treasure.loot.every(p=>p.taken));
let fight=h.get().rooms.find(r=>r.kind==='battle');h.enterRoom(fight.id);h.downHost();assert.equal(h.get().state,'play');assert.equal(h.get().player.hp,0);h.wipe();h.tick();assert.equal(h.get().player.hp,1);assert(fight.clear);h.tick(5);assert.equal(g.get().player.hp,1);
let bossRoom=h.get().rooms.find(r=>r.kind==='boss');h.enterRoom(bossRoom.id);h.unprotect();h.damagePartner();assert.equal(bossRoom.bossDamage,1,'damage to either player invalidates flawless boss deal');h.downHost();h.downPartner();assert.equal(h.get().state,'over');h.tick(5);assert.equal(g.get().state,'over');gs.close();assert.equal(h.els['panel-title'].textContent,'Connection ended');});
test('Malformed and oversized payload handling; rate limits',()=>{let l=createLobby({now:()=>0}),s=new Socket();l.attach(s);s.emit('message',Buffer.from('{'));assert.equal(s.messages.at(-1).type,'error');for(let i=0;i<95;i++)s.post({type:'none'});assert.equal(s.readyState,3);});
test('Full menu navigation, immediate solo start, pause, confirmation and locally persisted settings',()=>{let storage=new Map(),h=game(new Socket(),storage),e=h.els;assert.equal(e['menu-screen'].hidden,false);assert.equal(e['play-screen'].hidden,true);e['menu-help'].click();assert.equal(e['view-help'].hidden,false);e['menu-back'].click();assert.equal(e['menu-home'].hidden,false);e['menu-settings'].click();e['setting-volume'].value='35';e['setting-volume'].oninput();e['setting-music'].checked=false;e['setting-music'].onchange();e['setting-touch'].value='on';e['setting-touch'].onchange();e['setting-motion'].checked=true;e['setting-motion'].onchange();assert.equal(e.app.dataset.touch,'on');assert.equal(e.app.dataset.motion,'reduce');assert.equal(e['volume-value'].textContent,'35%');let again=game(new Socket(),storage);assert.equal(again.els['setting-volume'].value,35);assert.equal(again.els['setting-music'].checked,false);assert.equal(again.els.app.dataset.touch,'on');e['menu-back'].click();e['menu-solo'].click();assert.equal(e['view-characters'].hidden,false);e['char-confirm'].click();assert.equal(e['menu-screen'].hidden,true);assert.equal(h.get().state,'play');e['menu-open'].click();assert.equal(h.get().state,'paused');assert.equal(e['view-session'].hidden,false);e['session-settings'].click();assert.equal(e['view-settings'].hidden,false);e['menu-back'].click();assert.equal(e['view-session'].hidden,false);e['menu-quit'].click();assert.equal(e['view-quit'].hidden,false);e['cancel-quit'].click();assert.equal(h.get().state,'paused');e['menu-resume'].click();assert.equal(h.get().state,'play');assert.equal(e['menu-screen'].hidden,true);e['menu-open'].click();e['menu-quit'].click();e['confirm-quit'].click();assert.equal(h.get().state,'home');assert.equal(e['menu-home'].hidden,false);});
test('Menu validates codes, displays host invite, starts both clients, and cancels waiting rooms',()=>{let lobby=createLobby(),hs=new Socket(),gs=new Socket();lobby.attach(hs);lobby.attach(gs);let h=game(hs),g=game(gs);h.els['menu-host'].click();h.els['char-confirm'].click();h.els['host-online'].click();let code=h.net.code;assert.equal(code.length,6);assert.equal(h.els['invite-code'].textContent,code);assert.equal(h.els.invite.hidden,false);assert.equal(h.els['host-online'].disabled,true);g.els['menu-join'].click();g.els['char-confirm'].click();g.els['room-code'].value='bad';g.els['join-online'].click();assert.match(g.els['online-status'].textContent,/six-character/);assert.equal(g.net.role,'solo');g.els['room-code'].value=code.toLowerCase();g.els['join-online'].click();h.tick(5);assert.equal(h.get().state,'play');assert.equal(g.get().state,'play');assert.equal(h.els['menu-screen'].hidden,true);assert.equal(g.els['menu-screen'].hidden,true);
let lonelySocket=new Socket();lobby.attach(lonelySocket);let lonely=game(lonelySocket);lonely.els['menu-host'].click();lonely.els['char-confirm'].click();lonely.els['host-online'].click();let loneCode=lonely.net.code;lonely.els['menu-back'].click();assert.equal(lonely.els['view-quit'].hidden,false);lonely.els['confirm-quit'].click();assert.equal(lobby.rooms.has(loneCode),false);assert.equal(lonely.els['menu-home'].hidden,false);});
function startSolo(id){let h=game(new Socket());h.els['menu-solo'].click();h.els['choose-'+id].click();h.els['char-confirm'].click();return h;}
test('Four character starting kits, damage and movement match the selection sheet',()=>{for(let [id,hp,dmg,speed,fire] of [['rook',3,1,200,1],['frost',2,.9,210,1.15],['hop',2,.85,250,1.2],['ember',4,1.35,170,.8]]){let h=startSolo(id),p=h.get().player;assert.equal(p.characterId,id);assert.equal(p.hp,hp);assert.equal(h.maxLives(p),hp);assert(Math.abs(h.shotDamage(p)-dmg)<1e-9);assert.equal(h.stepSpeed(p),speed);assert.equal(h.shotRate(p),fire);h.keys.add('arrowup');h.tick();let b=h.get().shots[0];assert.equal(b.owner,id);assert(Math.abs(b.damage-dmg)<1e-9);assert.equal(b.chill,id==='frost');}});
test('Passive abilities: Rook extra healing, Frost slow, Ember low-life damage',()=>{let r=startSolo('rook'),room=r.get().rooms.find(x=>x.kind==='battle');r.enterRoom(room.id);r.get().player.hp=2;r.wipe();r.tick();assert.equal(r.get().player.hp,2);r.goFloor(1);r.wipe();r.tick();assert.equal(r.get().player.hp,3);assert.equal(r.useAbility(r.get().player),false);let f=startSolo('frost');let enemy={id:123,hp:10};f.hitEnemy(enemy,{damage:.9,chill:true});assert.equal(enemy.hp,9.1);assert.equal(enemy.chill,1.2);assert.equal(f.useAbility(f.get().player),false);let e=startSolo('ember');e.get().player.hp=3;assert(Math.abs(e.shotDamage(e.get().player)-1.7)<1e-9);});
test('Active abilities obey cooldown, death and pause; only Hop ignores damage',()=>{let h=startSolo('hop'),p=h.get().player;h.unprotect();assert.equal(h.useAbility(p),true);assert.equal(h.stepSpeed(p),500);h.damagePlayer();assert.equal(p.hp,2);assert.equal(h.useAbility(p),false);h.abilityStep(.5);assert.equal(h.stepSpeed(p),250);assert(p.abilityCooldown>4);h.abilityStep(5);assert.equal(p.abilityCooldown,0);h.els.pause.click();assert.equal(h.useAbility(p),false);h.els.pause.click();assert.equal(h.useAbility(p),true);p.hp=0;h.abilityStep(6);assert.equal(h.useAbility(p),false);let e=startSolo('ember');assert.equal(e.useAbility(e.get().player),true);assert.equal(e.shotRate(e.get().player),1.6);e.abilityStep(3.1);assert.equal(e.shotRate(e.get().player),.8);assert(e.get().player.abilityCooldown>8);});
test('Independent co-op characters, guest projectile stats, abilities, private upgrades and collector-only deal safety',()=>{let l=createLobby(),hs=new Socket(),gs=new Socket();l.attach(hs);l.attach(gs);let h=game(hs),g=game(gs);h.els['menu-host'].click();h.els['choose-frost'].click();h.els['char-confirm'].click();h.els['host-online'].click();g.els['menu-join'].click();g.els['choose-ember'].click();g.els['char-confirm'].click();g.els['room-code'].value=h.net.code;g.els['join-online'].click();h.tick(5);assert.equal(h.get().player.characterId,'frost');assert.equal(h.get().partner.characterId,'ember');assert.equal(h.maxLives(h.get().player),2);assert.equal(h.maxLives(h.get().partner),4);assert.equal(g.get().partner.characterId,'ember');g.keys.add('arrowup');g.tick(3);h.tick();let b=h.get().shots.find(x=>x.owner==='ember');assert(b);assert(Math.abs(b.damage-1.35)<1e-9);assert.equal(b.chill,false);g.els['ability-button'].click();assert.equal(h.get().partner.abilityCooldown,12);assert.equal(h.get().player.boostTime,0);g.els['ability-button'].click();assert.equal(h.get().partner.abilityCooldown,12);h.take(h.items.find(x=>x.id==='health'));assert.equal(h.maxLives(h.get().player),3);assert.equal(h.maxLives(h.get().partner),4);h.tick(5);assert(Math.abs(g.get().partner.abilityCooldown-h.get().partner.abilityCooldown)<.08,'cooldown follows within one snapshot interval');
let room=h.get().rooms[h.get().current];function deal(){room.loot=[{item:{id:'test-deal',name:'Test deal',text:'',take(){}},nx:.7,ny:.5,price:0,maxCost:2,taken:false}];h.pickPartner();h.pickupItems(1);return room.loot[0].taken;}assert.equal(deal(),true,'guest can afford a deal despite host having only 3 maximum lives');assert.equal(h.maxLives(h.get().player),3,'deal does not charge host life');assert.equal(h.maxLives(h.get().partner),2);assert.equal(deal(),false,'deal must leave its collector at least 2 maximum lives');});
test('Relay allowlists character IDs and only relays guest ability requests',()=>{let l=createLobby(),h=new Socket(),g=new Socket();l.attach(h);l.attach(g);h.post({type:'create',characterId:'not-real'});let code=h.messages[0].code;assert.equal(h.messages[0].characterId,'rook');g.post({type:'join',code,characterId:'hop',damage:999});assert.equal(h.messages.at(-1).characterId,'hop');let n=g.messages.length;h.post({type:'ability-request'});assert.equal(g.messages.length,n);g.post({type:'ability-request',damage:999});assert.deepEqual(h.messages.at(-1),{type:'ability-request'});});
test('Campaign milestones replace only their fixed-floor bosses and end at floor 12',()=>{let h=startSolo('rook');for(let [floor,type] of [[3,6],[6,7],[9,8],[12,9]]){h.goFloor(floor);assert.equal(h.get().boss.type,type);assert.equal(h.get().boss.champion,false);assert.equal(h.get().boss.r,48);}h.goFloor(4);assert([0,1,2,3,4,5,10,11,12].includes(h.get().boss.type));h.goFloor(12);h.wipe();h.tick();assert.equal(h.get().rooms[h.get().current].portal,true);h.descend();assert.equal(h.get().state,'over');assert.match(h.els['panel-title'].textContent,/Shift complete/);assert.equal(h.els.floor.textContent,'12 / 12');});
test('All four major bosses attack; shapeshifter teleports only after its landing warning',()=>{let h=startSolo('rook');for(let floor of [3,6,9,12]){h.goFloor(floor);h.get().boss.fire=0;h.bossUpdate(.02);assert(h.get().bullets.length+h.get().hazards.length>0);assert(h.get().boss.attack.length>0);}h.goFloor(12);let b=h.get().boss;b.age=12.1;b.fire=0;h.bossUpdate(.02);assert.equal(b.form,3);assert(b.teleport);let x=b.x,y=b.y,target={...b.teleport};assert.equal(h.get().hazards.length,1);h.bossUpdate(.5);assert.equal(b.x,x);assert.equal(b.y,y);h.bossUpdate(.7);assert.equal(b.x,target.x);assert.equal(b.y,target.y);assert.equal(b.teleport,null);});
test('Hazards are harmless while warning, damage only when active, and clear with the room',()=>{let h=startSolo('rook');h.goFloor(3);h.unprotect();let p=h.get().player,before=p.hp;h.hazardCircle(p.x,p.y,40,.5,.4);h.hazardsStep(.3);assert.equal(p.hp,before);h.hazardsStep(.25);assert.equal(p.hp,before-1);assert.equal(h.get().rooms[h.get().current].bossDamage,1);h.hazardsStep(1);assert.equal(h.get().hazards.length,0);h.hazardBeam(p.x,0,50,1,.4);h.wipe();h.tick();assert.equal(h.get().hazards.length,0);});
test('Permanent boss marks are courier-specific, immediate, idempotent and survive a reload',()=>{let storage=new Map(),h=game(new Socket(),storage);h.els['menu-solo'].click();h.els['choose-hop'].click();h.els['char-confirm'].click();h.goFloor(1);h.wipe();h.tick();assert.equal(h.get().runMilestones.length,0);h.goFloor(3);h.wipe();h.tick();let saved=JSON.parse(storage.get('kitchen-crawl-completions-v1'));assert.equal(saved.hop.heart,true);assert.equal(saved.rook.heart,undefined);assert.equal(h.recordMark('hop','heart'),false);assert.equal(h.recordMark('made-up','heart'),false);assert.equal(h.recordMark('hop','made-up'),false);let reload=game(new Socket(),storage);reload.els['menu-solo'].click();assert.equal(reload.els['mark-heart'].dataset.complete,'true');assert.equal(reload.els['completion-count'].textContent,'1 / 4 complete');reload.els['choose-frost'].click();assert.equal(reload.els['mark-heart'].dataset.complete,'false');assert.equal(reload.els['completion-count'].textContent,'0 / 4 complete');});
test('Co-op marks save to separate browsers for the correct courier, even after a missed clear snapshot',()=>{let l=createLobby(),hs=new Socket(),gs=new Socket();l.attach(hs);l.attach(gs);let hostStore=new Map(),guestStore=new Map(),h=game(hs,hostStore),g=game(gs,guestStore);h.els['menu-host'].click();h.els['choose-frost'].click();h.els['char-confirm'].click();h.els['host-online'].click();g.els['menu-join'].click();g.els['choose-ember'].click();g.els['char-confirm'].click();g.els['room-code'].value=h.net.code;g.els['join-online'].click();h.tick(5);h.goFloor(6);let receive=gs.receive;gs.receive=()=>{};h.wipe();h.tick(5);assert.equal(guestStore.has('kitchen-crawl-completions-v1'),false);h.descend();gs.receive=receive;h.tick(5);let a=JSON.parse(hostStore.get('kitchen-crawl-completions-v1')),b=JSON.parse(guestStore.get('kitchen-crawl-completions-v1'));assert.equal(a.frost.warden,true);assert.equal(a.ember.warden,undefined);assert.equal(b.ember.warden,true);assert.equal(b.frost.warden,undefined);assert.deepEqual(g.get().runMilestones,['warden']);});
test('Blocked completion storage keeps a session mark and reports it accurately',()=>{let blocked={get:()=>null,set(){throw Error('Blocked')}},h=game(new Socket(),blocked);assert.equal(h.recordMark('rook','deep'),true);h.els['menu-solo'].click();assert.equal(h.els['mark-deep'].dataset.complete,'true');assert.match(h.els['completion-note'].textContent,/session only/);});

test('Brutal healing: no room-clear or next-floor heal; cafe restores only one life',()=>{let h=startSolo('frost'),p=h.get().player;p.hp=1;let fight=h.get().rooms.find(r=>r.kind==='battle');h.enterRoom(fight.id);h.wipe();h.tick();assert.equal(p.hp,1);h.descend();assert.equal(p.hp,1);let rest=h.get().rooms.find(r=>r.kind==='rest');if(rest){h.enterRoom(rest.id);assert.equal(p.hp,2);p.hp=1;h.enterRoom(rest.id);assert.equal(p.hp,1);}h.take(h.items.find(i=>i.id==='health'));assert.equal(h.maxLives(p),3);assert.equal(p.hp,2);});
test('All nine regular bosses attack and never award a completion mark',()=>{for(let type of [0,1,2,3,4,5,10,11,12]){let h=startSolo('rook');h.goFloor(1);let r=h.get().rooms[h.get().current];r.bossKind=type;r.champion=false;h.spawnBoss();let b=h.get().boss;assert.equal(h.isMajorBoss(type),false);assert.equal(b.max,112);b.phase=1;b.fire=0;h.bossUpdate(.02);assert(h.get().bullets.length>0);if(type!==11)assert(h.get().hazards.length>0);assert(b.attack.length>0);let normalShots=h.get().bullets.length;b.hp=b.max/3;b.fire=0;h.bossUpdate(.02);assert(h.get().bullets.length>normalShots);assert(b.fire<1.2);h.wipe();h.tick();assert.equal(h.get().runMilestones.length,0);assert.equal(Object.keys(h.get().completionMarks.rook).length,0);}});
test('Regular pool includes new bosses, preserves milestones, and scales enemy rooms past six',()=>{let h=startSolo('rook'),seen=[];for(let f=1;f<=12;f++){h.goFloor(f);let type=h.get().boss.type;if(![3,6,9,12].includes(f)){assert(h.regularBossTypes.includes(type));seen.push(type);}}assert.equal(new Set(seen).size,8);assert(seen.some(t=>t>=10));h.goFloor(12);h.spawnEnemies();assert.equal(h.get().enemies.length,10);for(let e of h.get().enemies)assert(e.hp>=20);});
test('New random boss hazards and state synchronize to the guest',()=>{let l=createLobby(),hs=new Socket(),gs=new Socket();l.attach(hs);l.attach(gs);let h=game(hs),g=game(gs);hs.post({type:'create'});gs.post({type:'join',code:h.net.code});h.goFloor(2);let r=h.get().rooms[h.get().current];r.bossKind=12;h.spawnBoss();h.get().boss.fire=0;h.bossUpdate(.02);g.applySnapshot(h.makeSnapshot());assert.equal(g.get().boss.type,12);assert(g.get().hazards.length>0);assert.equal(g.get().runMilestones.length,0);});

test('Random branching grids stay connected, leave empty cells, and keep bosses reachable without keys',()=>{let h=startSolo('rook'),sizes=new Set();for(let n=0;n<90;n++){h.goFloor(2);let {rooms,gridSize,startRoom}=h.get();sizes.add(gridSize);assert(gridSize>=6&&gridSize<=12);assert.equal(rooms.length,gridSize*gridSize);let active=rooms.filter(r=>r.kind!=='void');assert(active.length>=gridSize*2&&active.length<=gridSize*3+1);assert(active.length<rooms.length);let seen=new Set([startRoom]),queue=[startRoom];for(let id of queue)for(let d of rooms[id].edges){let next=id+[0,1,0,-1][d]+[ -1,0,1,0][d]*gridSize;assert(rooms[next]&&rooms[next].kind!=='void');assert(rooms[next].edges.includes((d+2)%4));if(!seen.has(next)){seen.add(next);queue.push(next)}}assert.equal(seen.size,active.length);let boss=rooms.find(r=>r.kind==='boss'),treasure=rooms.find(r=>r.kind==='treasure');assert.equal(boss.edges.length,1);assert.equal(treasure.edges.length,1);assert.equal(treasure.locked,true);let reachable=new Set([startRoom]),q=[startRoom];for(let id of q)for(let d of rooms[id].edges){let next=id+[0,1,0,-1][d]+[-1,0,1,0][d]*gridSize;if(!rooms[next].locked&&!reachable.has(next)){reachable.add(next);q.push(next)}}assert(reachable.has(boss.id));assert(rooms[startRoom].pickups.some(p=>p.kind==='key'));assert(active.some(r=>r.chests.length));}assert.equal(sizes.size,1);assert(sizes.has(6));});
test('Item rooms are free on floor 1, cost one key from floor 2, and stay unlocked',()=>{let h=startSolo('rook'),r=h.get().rooms.find(r=>r.kind==='treasure');assert.equal(r.locked,false);h.setKeys(0);h.enterRoom(r.id);assert.equal(h.get().current,r.id);h.goFloor(2);r=h.get().rooms.find(r=>r.kind==='treasure');let before=h.get().current;assert.equal(h.enterRoom(r.id),false);assert.equal(h.get().current,before);h.setKeys(1);h.enterRoom(r.id);assert.equal(h.get().keyCount,0);assert.equal(r.locked,false);assert(r.loot.length>0);h.enterRoom(h.get().startRoom);h.enterRoom(r.id);assert.equal(h.get().current,r.id);assert.equal(h.get().keyCount,0);});
test('Chests scatter collectible coins once, require keys only after floor 1, and persist on revisit',()=>{let h=startSolo('rook');for(let floor of [1,2]){h.goFloor(floor);let r=h.get().rooms.find(r=>r.chests.length);h.enterRoom(r.id);h.wipe();h.tick();let chest=r.chests[0],p=h.get().player;p.x=chest.x;p.y=chest.y;h.setKeys(0);let coins=h.get().coins;h.worldLoot(.02);if(floor===2){assert.equal(chest.opened,false);h.setKeys(1);h.worldLoot(.02);assert.equal(h.get().keyCount,0);}assert.equal(chest.opened,true);let spilled=r.pickups.filter(p=>p.kind==='coin');assert(spilled.length>=2&&spilled.length<=4);assert(spilled.some(p=>Math.abs(p.vx)>0));for(let i=0;i<80;i++)h.worldLoot(.02);for(let coin of [...r.pickups]){p.x=coin.x;p.y=coin.y;h.worldLoot(.02);}assert(h.get().coins>=coins+2);h.enterRoom(h.get().startRoom);h.enterRoom(r.id);assert.equal(r.chests[0].opened,true);h.worldLoot(1);assert.equal(r.pickups.filter(p=>p.kind==='coin').length,0);}});
test('Guaranteed floor key and shop purchase add shared keys only once',()=>{let h=startSolo('rook');h.goFloor(2);h.enterRoom(h.get().startRoom);let r=h.get().rooms[h.get().current],k=r.pickups.find(p=>p.kind==='key'),p=h.get().player;h.setKeys(0);p.x=k.x;p.y=k.y;h.worldLoot(.02);assert.equal(h.get().keyCount,1);h.worldLoot(.02);assert.equal(h.get().keyCount,1);let shop=h.get().rooms.find(r=>r.kind==='shop');h.enterRoom(shop.id);h.setCoins(20);let key=shop.loot.find(p=>p.item.id==='key');assert(key);p.x=key.nx*h.get().W;p.y=key.ny*h.get().H;let coins=h.get().coins;h.pickupItems(2);assert.equal(h.get().keyCount,2);assert.equal(h.get().coins,coins-10);h.pickupItems(2);assert.equal(h.get().keyCount,2);});
test('Cover blocks bodies, fast projectiles and dashes while leaving door lanes and spawns clear',()=>{let h=startSolo('hop'),r=h.get().rooms.find(r=>r.kind==='battle');h.enterRoom(r.id);let box=r.obstacles[0];assert(box);let p={x:box.x-20,y:box.y+box.h/2};h.moveBody(p,160,0,12);assert(p.x<=box.x-12);assert(h.coverHit(box.x-100,box.y+20,box.x+box.w+100,box.y+20,5));assert.equal(h.coverHit(0,h.get().H/2,h.get().W,h.get().H/2,0),false);for(let e of h.get().enemies)for(let o of r.obstacles)assert(!(e.x+e.r>o.x&&e.x-e.r<o.x+o.w&&e.y+e.r>o.y&&e.y-e.r<o.y+o.h));});
test('Large map snapshots preserve locks, chests, cover and keys within relay payload limit',()=>{let h=startSolo('rook');h.goFloor(2);h.setKeys(3);let snap=h.makeSnapshot();snap.partner={...snap.player,characterId:'hop'};let encoded=JSON.stringify({type:'snapshot',state:snap});assert(Buffer.byteLength(encoded)<262144);let g=game(new Socket());g.applySnapshot(JSON.parse(encoded).state);assert.equal(g.get().gridSize,h.get().gridSize);assert.equal(g.get().rooms.length,h.get().rooms.length);assert.equal(g.get().keyCount,3);let a=h.get().rooms.find(r=>r.chests.length),b=g.get().rooms[a.id];assert.equal(b.chests.length,a.chests.length);assert.equal(b.obstacles.length,a.obstacles.length);assert.equal(g.get().rooms.find(r=>r.kind==='treasure').locked,true);let before=g.get().rooms;g.applySnapshot({...snap,gridSize:99});assert.equal(g.get().rooms,before);});

test('Enemy key drops are collectible; cover actually absorbs hostile and piercing player shots',()=>{let h=startSolo('rook'),r=h.get().rooms.find(r=>r.kind==='battle');h.enterRoom(r.id);let enemy=h.get().enemies[0],random=Math.random;try{Math.random=()=>0;h.hitEnemy(enemy,{damage:10000});}finally{Math.random=random;}assert(r.pickups.some(p=>p.kind==='key'));let k=r.pickups.find(p=>p.kind==='key');h.get().player.x=k.x;h.get().player.y=k.y;let keys=h.get().keyCount;h.worldLoot(.02);assert.equal(h.get().keyCount,keys+1);h.wipe();h.tick();let box=r.obstacles[0],p=h.get().player;p.x=box.x+box.w+25;p.y=box.y+20;let hp=p.hp;h.unprotect();h.get().bullets.push({x:box.x-20,y:box.y+20,vx:4000,vy:0,r:5});h.get().shots.push({x:box.x-20,y:box.y+20,vx:4000,vy:0,r:5,life:2,damage:1,hit:new Set()});h.tick();assert.equal(h.get().bullets.length,0);assert.equal(h.get().shots.length,0);assert.equal(p.hp,hp);});

test('No prestige: old upgrade data is ignored and selecting a courier starts immediately without tokens',()=>{let old=JSON.stringify({tokens:999,health:3,power:3}),storage=new Map([['wolt-rogue-meta',old],['kitchen-crawl-completions-v1',JSON.stringify({rook:{heart:true}})]]);let h=game(new Socket(),storage);h.els['menu-solo'].click();assert.equal(h.els['mark-heart'].dataset.complete,'true');h.els['char-confirm'].click();assert.equal(h.get().state,'play');assert.equal(h.get().player.hp,3);assert.equal(h.shotDamage(h.get().player),1);assert.equal(h.els.panel.hidden,true);assert.equal(h.els.choices,undefined);h.goFloor(12);h.wipe();h.tick();h.descend();assert.equal(h.get().state,'over');assert.equal(storage.get('wolt-rogue-meta'),old);assert(!/tokens|earned|meta/.test(JSON.stringify(h.makeSnapshot())));});
test('Escape, P, pause button, settings back, and quit confirmation share the normal pause menu',()=>{let h=startSolo('hop'),e=h.els;h.useAbility(h.get().player);h.key('Escape');assert.equal(h.get().state,'paused');assert.equal(e['view-session'].hidden,false);assert.equal(e['menu-screen'].dataset.overlay,'true');assert.equal(e['play-screen'].hidden,false);let x=h.get().player.x,cooldown=h.get().player.abilityCooldown;h.keys.add('d');h.tick(10);assert.equal(h.get().player.x,x);assert.equal(h.get().player.abilityCooldown,cooldown);e['session-settings'].click();h.key('Escape');assert.equal(e['view-session'].hidden,false);assert.equal(h.get().state,'paused');h.key('p');assert.equal(h.get().state,'play');assert.equal(e['menu-screen'].hidden,true);h.key('p');assert.equal(h.get().state,'paused');e['menu-quit'].click();e['cancel-quit'].click();assert.equal(h.get().state,'paused');e['menu-resume'].click();assert.equal(h.get().state,'play');e.pause.click();assert.equal(h.get().state,'paused');h.key('Escape');assert.equal(h.get().state,'play');h.blur();assert.equal(h.get().state,'paused');assert.equal(e['view-session'].hidden,false);});
test('Fixed 6x6 floors mix standard and larger rooms with appropriately sized cover',()=>{let h=startSolo('rook'),layouts=new Set();assert.equal(h.get().W,760);assert.equal(h.get().H,440);for(let n=0;n<30;n++){h.newRun();let {rooms,gridSize}=h.get();assert.equal(gridSize,6);assert.equal(rooms.length,36);layouts.add(rooms.map(r=>r.edges.join('')).join('|'));assert(rooms.some(r=>r.width===1520));assert.equal(rooms[h.get().startRoom].width,760);for(let r of rooms.filter(r=>r.kind==='battle')){h.enterRoom(r.id);let {W,H}=h.get(),large=W>760;assert.equal(W,r.width);assert.equal(H,r.height);assert(r.obstacles.length>=(large?8:4)&&r.obstacles.length<=(large?12:6));assert.equal(h.coverHit(27,H/2,W-27,H/2,12),false);assert.equal(h.coverHit(W/2,27,W/2,H-27,12),false);for(let e of h.get().enemies)for(let o of r.obstacles)assert(!(e.x+e.r>o.x&&e.x-e.r<o.x+o.w&&e.y+e.r>o.y&&e.y-e.r<o.y+o.h));}}assert(layouts.size>1);});
test('Local cameras follow host and guest independently, clamp to boundaries, and spectate survivors',()=>{let l=createLobby(),hs=new Socket(),gs=new Socket();l.attach(hs);l.attach(gs);let h=game(hs),g=game(gs);hs.post({type:'create'});gs.post({type:'join',code:h.net.code});h.enterRoom(h.get().rooms.find(r=>r.kind==='battle'&&r.width===1520).id);h.get().player.x=100;h.get().player.y=100;h.get().partner.x=1400;h.get().partner.y=780;h.updateCamera();assert.equal(h.get().camera.x,0);assert.equal(h.get().camera.y,0);g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));g.updateCamera();assert.equal(g.get().camera.x,760);assert.equal(g.get().camera.y,440);assert(h.directionTargets().some(t=>t.label==='Partner'));g.get().partner.hp=0;g.updateCamera();assert.equal(g.get().camera.x,0);assert.equal(g.get().camera.y,0);let before=g.get().rooms;g.applySnapshot({...h.makeSnapshot(),worldW:760});assert.equal(g.get().rooms,before);});
test('Co-op pause menu freezes the team, allows guest settings and resumes from either player',()=>{let l=createLobby(),hs=new Socket(),gs=new Socket();l.attach(hs);l.attach(gs);let h=game(hs),g=game(gs);hs.post({type:'create'});gs.post({type:'join',code:h.net.code});h.tick(5);g.key('Escape');h.tick(5);assert.equal(h.get().state,'paused');assert.equal(g.get().state,'paused');assert.equal(h.els['view-session'].hidden,false);assert.equal(g.els['view-session'].hidden,false);g.els['session-settings'].click();h.tick(5);assert.equal(g.els['view-settings'].hidden,false);let x=h.get().partner.x;g.keys.add('d');g.tick(5);h.tick(5);assert.equal(h.get().partner.x,x);g.key('Escape');g.els['menu-resume'].click();h.tick(5);assert.equal(h.get().state,'play');assert.equal(g.get().state,'play');assert.equal(g.els['menu-screen'].hidden,true);h.els.pause.click();h.tick(5);assert.equal(g.get().state,'paused');h.els['menu-resume'].click();h.tick(5);assert.equal(g.get().state,'play');});

test('Duplicate co-op pause requests are idempotent rather than accidentally resuming',()=>{let l=createLobby(),hs=new Socket(),gs=new Socket();l.attach(hs);l.attach(gs);let h=game(hs);game(gs);hs.post({type:'create'});gs.post({type:'join',code:h.net.code});gs.post({type:'pause-request',paused:true});gs.post({type:'pause-request',paused:true});assert.equal(h.get().state,'paused');gs.post({type:'pause-request',paused:false});gs.post({type:'pause-request',paused:false});assert.equal(h.get().state,'play');});

test('Standard rooms never scroll and camera resets on size changes in both clients',()=>{let l=createLobby(),hs=new Socket(),gs=new Socket();l.attach(hs);l.attach(gs);let h=game(hs),g=game(gs);hs.post({type:'create'});gs.post({type:'join',code:h.net.code});let large=h.get().rooms.find(r=>r.width===1520);h.enterRoom(large.id);h.get().player.x=1400;h.get().player.y=800;h.updateCamera();assert.equal(h.get().camera.x,760);g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));assert.equal(g.get().W,1520);h.enterRoom(h.get().startRoom);h.get().player.x=720;h.get().player.y=400;h.updateCamera();assert.equal(h.get().camera.x,0);assert.equal(h.get().camera.y,0);g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));g.updateCamera();assert.equal(g.get().W,760);assert.equal(g.get().camera.x,0);assert.equal(g.get().camera.y,0);h.goFloor(3);assert.equal(h.get().W,1520);h.goFloor(1);assert.equal(h.get().W,760);});
test('Off-screen markers never reveal enemies or bosses',()=>{let h=startSolo('rook');h.goFloor(3);assert(h.get().boss);assert.equal(h.directionTargets().some(t=>['Enemy','Boss'].includes(t.label)),false);let r=h.get().rooms.find(r=>r.kind==='battle'&&r.width===1520);h.enterRoom(r.id);assert(h.get().enemies.length);assert.equal(h.directionTargets().some(t=>['Enemy','Boss'].includes(t.label)),false);});
test('Damage numbers reflect hit damage and player hurt, expire, and obey pause',()=>{let h=startSolo('rook');h.goFloor(1);let b=h.get().boss;h.hitEnemy(b,{damage:1.35});assert.equal(h.get().combatTexts.at(-1).text,'−1.35');h.unprotect();h.damagePlayer();assert.equal(h.get().combatTexts.at(-1).text,'−1');assert.equal(h.get().combatTexts.at(-1).hurt,true);assert.equal(h.get().player.damageFlash,.3);let count=h.get().combatTexts.length;h.damagePlayer();assert.equal(h.get().combatTexts.length,count);h.key('Escape');let life=h.get().combatTexts[0].life;h.tick(5);assert.equal(h.get().combatTexts[0].life,life);h.key('Escape');h.feedbackStep(1);assert.equal(h.get().combatTexts.length,0);assert.equal(h.get().player.damageFlash,0);h.unprotect();h.damagePlayer();h.enterRoom(h.get().startRoom);assert.equal(h.get().combatTexts.length,0);assert.equal(h.get().player.damageFlash,0);});
test('Guest damage feedback synchronizes and reduced motion keeps labels stationary',()=>{let l=createLobby(),hs=new Socket(),gs=new Socket();l.attach(hs);l.attach(gs);let h=game(hs),g=game(gs);hs.post({type:'create'});gs.post({type:'join',code:h.net.code});h.unprotect();h.damagePartner();g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));assert.equal(g.get().partner.damageFlash,.3);assert.equal(g.get().combatTexts.at(-1).hurt,true);h.els['setting-motion'].checked=true;h.els['setting-motion'].onchange();let y=h.get().combatTexts[0].y;h.feedbackStep(.1);assert.equal(h.get().combatTexts[0].y,y);g.drawFeedback();});

function onlinePair(options){let lobby=createLobby(options),hs=new Socket(),gs=new Socket();lobby.attach(hs);lobby.attach(gs);let h=game(hs),g=game(gs);hs.post({type:'create'});gs.post({type:'join',code:h.net.code});h.tick(5);return {h,g,hs,gs,lobby};}
test('Guest predicts immediately before the host receives movement, then reconciles acknowledgments',()=>{let {h,g,hs,gs}=onlinePair(),wire=[],receive=hs.receive;hs.receive=m=>wire.push(m);let old=g.get().partner.x,host=h.get().partner.x;g.keys.add('d');g.tick();assert(g.get().partner.x>old,'moves without waiting for a server round trip');assert.equal(h.get().partner.x,host);for(let m of wire)receive(m);h.tick(2);assert(h.get().remoteAck>0);g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));assert.equal(g.get().pendingInputs.length,0);assert(Math.abs(g.get().partner.x-h.get().partner.x)<.001);});
test('Prediction survives 160ms round-trip latency with jitter and converges after releasing movement',()=>{let now=0,{h,g,hs,gs}=onlinePair({now:()=>now}),queue=[],hr=hs.receive,gr=gs.receive;hs.receive=m=>queue.push({at:now+80+(queue.length%3)*10,receive:hr,m});gs.receive=m=>queue.push({at:now+80+(queue.length%2)*10,receive:gr,m});for(let n=0;n<150;n++){now+=20;let ready=queue.filter(x=>x.at<=now);queue=queue.filter(x=>x.at>now);for(let x of ready)x.receive(x.m);g.keys.clear();if(n<90)g.keys.add(Math.floor(n/10)%2?'a':'d');g.tick();h.tick();assert(g.get().pendingInputs.length<120);assert.equal(g.get().state,'play');}assert(Math.abs(g.get().partner.x-h.get().partner.x)<.1);assert(h.get().remoteAck>100);});
test('Prediction and replay respect crates, room changes, pause, death, and stale connections',()=>{let {h,g}=onlinePair(),r=h.get().rooms.find(r=>r.kind==='battle'),o=r.obstacles[0];h.enterRoom(r.id);h.get().partner.x=o.x-15;h.get().partner.y=o.y+o.h/2;g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));g.keys.add('d');for(let n=0;n<8;n++)g.tick();assert(g.get().partner.x<=o.x-12);let x=g.get().partner.x;g.key('Escape');h.tick(4);g.tick(4);assert.equal(g.get().state,'paused');assert.equal(g.get().partner.x,h.get().partner.x);h.enterRoom(h.get().startRoom);g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));assert.equal(g.get().pendingInputs.length,0);g.get().partner.hp=0;g.keys.add('d');x=g.get().partner.x;g.tick(4);assert.equal(g.get().partner.x,x);g.get().partner.hp=3;g.tick(40);x=g.get().partner.x;g.tick(10);assert.equal(g.get().partner.x,x,'prediction stops when updates stop');});
test('Compact snapshots reduce bytes, retain room loot, and recover missing keyframes',()=>{let {h,g}=onlinePair();let full=h.makeNetworkSnapshot();if(!full.rooms){h.newRun();full=h.makeNetworkSnapshot();}g.applyNetworkSnapshot(JSON.parse(JSON.stringify(full)));let compact=h.makeNetworkSnapshot();assert.equal(compact.rooms,undefined);assert(compact.room);assert(JSON.stringify(compact).length<JSON.stringify(full).length*.7);compact.keyCount=7;g.applyNetworkSnapshot(JSON.parse(JSON.stringify(compact)));assert.equal(g.get().keyCount,7);let fresh=game(new Socket());fresh.applyNetworkSnapshot(JSON.parse(JSON.stringify(compact)));assert.equal(fresh.get().rooms.length,0);fresh.applyNetworkSnapshot(JSON.parse(JSON.stringify(full)));fresh.applyNetworkSnapshot(JSON.parse(JSON.stringify(compact)));assert.equal(fresh.get().keyCount,7);let before=g.get().keyCount;g.applyNetworkSnapshot({...compact,layoutVersion:999,keyCount:99});assert.equal(g.get().keyCount,before);});
test('Relay bounds command batches, removes invalid movement data, and deduplicates at the host',()=>{let {h,hs,gs}=onlinePair(),room=h.roomKey(),cmd={seq:1,dt:.02,keys:['d','evil','d'],aim:999,room};gs.post({type:'input',keys:['d'],commands:[cmd,{...cmd,seq:2,dt:999},{...cmd,seq:-1}]});let packet=hs.messages.at(-1);assert.equal(packet.commands.length,1);assert.deepEqual(packet.commands[0].keys,['d']);assert.equal(packet.commands[0].aim,2);let x=h.get().partner.x;h.tick();assert.equal(h.get().remoteAck,1);let moved=h.get().partner.x;assert(moved>x);gs.post({type:'input',keys:['d'],commands:[cmd]});h.tick();assert.equal(h.get().partner.x,moved);gs.post({type:'input',keys:['d'],commands:[{...cmd,seq:2,room:'old-room'}]});h.tick();assert.equal(h.get().partner.x,moved);});
test('Render smoothing never mutates authoritative positions and snaps large teleports',()=>{let h=startSolo('rook'),p={x:100,y:100,hp:3};h.smoothPosition(p,'test',.02);p.x=140;let rendered=h.smoothPosition(p,'test',.02);assert(rendered.x>100&&rendered.x<140);assert.equal(p.x,140);p.x=500;assert.equal(h.smoothPosition(p,'test',.02).x,500);});
test('Client transport reports backpressure instead of queueing stale updates indefinitely',()=>{let box={window:{},WebSocket:{OPEN:1}},source=fs.readFileSync(path.join(__dirname,'../public/coop.js'),'utf8');vm.createContext(box);vm.runInContext(source,box);let c=box.window.Coop,sent=[];assert.equal(c.send({type:'input'}),false);c.socket={readyState:1,bufferedAmount:70000,send:m=>sent.push(m)};assert.equal(c.send({type:'input'}),false);c.socket.bufferedAmount=0;assert.equal(c.send({type:'input'}),true);assert.equal(sent.length,1);});

test('A new hosted run resets command acknowledgments for a newly joining client',()=>{let {h,gs}=onlinePair();gs.post({type:'input',keys:['d'],commands:[{seq:50,dt:.02,keys:['d'],aim:2,room:h.roomKey()}]});h.tick();assert.equal(h.get().remoteAck,50);h.newRun();assert.equal(h.get().remoteAck,0);gs.post({type:'input',keys:['d'],commands:[{seq:1,dt:.02,keys:['d'],aim:2,room:h.roomKey()}]});let x=h.get().partner.x;h.tick();assert.equal(h.get().remoteAck,1);assert(h.get().partner.x>x);});
test('Periodic full snapshots automatically restore a guest that missed the first baseline',()=>{let {h,g,gs}=onlinePair();h.newRun();let full=h.makeNetworkSnapshot(),compact=h.makeNetworkSnapshot(),fresh=game(new Socket());fresh.applyNetworkSnapshot(JSON.parse(JSON.stringify(compact)));assert.equal(fresh.get().rooms.length,0);let before=gs.messages.length;h.tick(55);let recovered=gs.messages.slice(before).find(m=>m.type==='snapshot'&&m.state.rooms);assert(recovered);fresh.applyNetworkSnapshot(JSON.parse(JSON.stringify(recovered.state)));assert.equal(fresh.get().rooms.length,36);assert.equal(fresh.get().current,h.get().current);});


test('Every recipe and deal modifies only its collector, including healing and max lives',()=>{for(let id of ['damage','rapid','spread','pierce','chili','bounce','health','speed','halo','grace','wings','inferno','pact','hunger']){let {h}=onlinePair(),host=h.get().player,guest=h.get().partner;host.hp=1;guest.hp=1;let before=JSON.stringify(h.gear(host)),guestBefore=JSON.stringify(h.gear(guest));let item=[...h.items,...h.dealItems].find(i=>i.id===id);h.take(item,guest);assert.equal(JSON.stringify(h.gear(host)),before,id+' leaves host unchanged');assert.notEqual(JSON.stringify(h.gear(guest)),guestBefore);assert.equal(host.hp,1);assert.equal(guest.hp,['health','halo','wings'].includes(id)?2:1);assert.equal(guest.inventory.build.at(-1),item.name);}});
test('Host and guest projectile modifiers are independent and frozen when fired',()=>{let {h,g}=onlinePair(),a=h.get().player,b=h.get().partner;for(let id of ['damage','spread','pierce','chili','bounce'])h.take(h.items.find(i=>i.id===id),b);h.shoot(0,a);h.shoot(0,b);let shots=h.get().shots;assert.equal(shots.length,4);assert.equal(shots[0].damage,1);assert.equal(shots[0].chili,false);assert.equal(shots[0].pierce,false);assert.equal(shots[0].bounce,false);for(let shot of shots.slice(1)){assert.equal(shot.damage,2);assert.equal(shot.chili,true);assert.equal(shot.pierce,true);assert.equal(shot.bounce,true);}let enemy={id:999,hp:10,x:100,y:100};h.hitEnemy(enemy,shots[0]);assert(!enemy.burn);h.hitEnemy(enemy,shots[1]);assert.equal(enemy.burn,2);h.take(h.items.find(i=>i.id==='damage'),b);assert.equal(shots[1].damage,2);g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));assert.equal(g.shotDamage(g.get().player),1);assert.equal(g.shotDamage(g.get().partner),3);assert.match(g.els.build.textContent,/Your recipes: Extra crispy/);assert.match(h.els.build.textContent,/Your recipes: Classic fries/);});
test('Guest purchases spend shared coins but grant personal recipes, meals and max-life costs',()=>{let {h,g}=onlinePair(),host=h.get().player,guest=h.get().partner;let shop=h.get().rooms.find(r=>r.kind==='shop');h.enterRoom(shop.id);h.setCoins(20);let item=h.items.find(i=>i.id==='damage');shop.loot=[{item,nx:.7,ny:.5,price:20,taken:false}];h.pickPartner();h.pickupItems(1);assert.equal(h.get().coins,0);assert.equal(h.shotDamage(host),1);assert.equal(h.shotDamage(guest),2);host.hp=1;guest.hp=1;shop.loot=[{item:{id:'meal'},nx:.7,ny:.5,price:0,taken:false}];h.pickPartner();h.pickupItems(1);assert.equal(host.hp,1);assert.equal(guest.hp,2);h.take(h.items.find(i=>i.id==='health'),guest);assert.equal(h.maxLives(guest),4);shop.loot=[{item:h.dealItems.find(i=>i.id==='inferno'),nx:.7,ny:.5,price:0,maxCost:2,taken:false}];h.pickPartner();h.pickupItems(1);assert.equal(h.maxLives(host),3);assert.equal(h.maxLives(guest),2);assert.equal(h.shotDamage(host),1);assert.equal(h.shotDamage(guest),5);g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));assert.equal(g.get().coins,0);assert.equal(g.maxLives(g.get().partner),2);});
test('Inventory caps are personal and new runs clear both inventories without clearing marks',()=>{let {h}=onlinePair(),host=h.get().player,guest=h.get().partner;let pierce=h.items.find(i=>i.id==='pierce');h.take(pierce,host);assert.equal(h.canEquip(pierce,host),false);assert.equal(h.canEquip(pierce,guest),true);h.take(h.items.find(i=>i.id==='speed'),guest);assert.equal(h.stepSpeed(host),200);assert(Math.abs(h.stepSpeed(guest)-230)<1e-9);h.recordMark('rook','heart');h.newRun();assert.equal(h.get().build.length,0);assert.equal(h.get().partner.inventory.build.length,0);assert.equal(h.gear(h.get().player).pierce,false);assert.equal(h.stepSpeed(h.get().partner),200);assert.equal(h.get().completionMarks.rook.heart,true);});


test('Economy starts poor, rewards fewer coins, and prices scale with rarity',()=>{let h=startSolo('rook');assert.equal(h.get().coins,3);let shop=h.get().rooms.find(r=>r.kind==='shop');h.enterRoom(shop.id);for(let loot of shop.loot.filter(p=>p.item.rarity))assert.equal(loot.price,h.rarityPrices[loot.item.rarity]);let coins=h.get().coins;h.get().player.x=shop.loot[0].nx*h.get().W;h.get().player.y=shop.loot[0].ny*h.get().H;h.pickupItems(1);assert.equal(h.get().coins,coins);assert.equal(shop.loot[0].taken,false);h.goFloor(1);let before=h.get().coins;h.wipe();h.tick();assert.equal(h.get().coins,before+11);let enemy={id:998,x:100,y:100,r:17,hp:1},random=Math.random;try{Math.random=()=>.9;h.hitEnemy(enemy,{damage:2});assert.equal(h.get().coins,before+11);}finally{Math.random=random;}});
test('Exactly twenty new items have usable effects, personal ownership and rarity metadata',()=>{let {h,g}=onlinePair();assert.equal(h.newItems.length,20);assert.equal(h.items.length,28);assert.equal(new Set(h.items.map(i=>i.id)).size,28);for(let row of h.newItems){let item=h.items.find(i=>i.id===row[0]);assert(item.text.length>15);assert(h.rarityWeights[item.rarity]>0);let before=JSON.stringify(h.gear(h.get().player));h.take(item,h.get().partner);assert.equal(JSON.stringify(h.gear(h.get().player)),before);assert(h.get().partner.inventory.build.includes(item.name));}g.applySnapshot(JSON.parse(JSON.stringify(h.makeSnapshot())));assert(g.gear(g.get().partner).special.homing);assert(g.gear(g.get().partner).special.explosive);assert.equal(g.get().partner.inventory.build.length,20);h.newRun();assert.equal(h.get().player.foilReady,false);assert.equal(h.get().partner.foilReady,false);assert.equal(Object.keys(h.gear(h.get().partner).special).length,0);});
test('Rarity-weighted offers sample without duplicates and rare items are actually scarce',()=>{let h=startSolo('rook'),counts={common:0,uncommon:0,rare:0,legendary:0};for(let n=0;n<1500;n++){let list=h.offers();assert.equal(list.length,3);assert.equal(new Set(list.map(i=>i.id)).size,3);for(let i of list)counts[i.rarity]++;}assert(counts.common>counts.uncommon*2);assert(counts.uncommon>counts.rare);assert(counts.rare>counts.legendary*3);assert(counts.legendary>0);});
test('Homing turns gradually toward visible targets and respects cover',()=>{let h=startSolo('rook');h.goFloor(1);let boss=h.get().boss;boss.x=250;boss.y=200;let b={x:100,y:100,vx:410,vy:0,homing:true};h.steerShot(b,.1);assert(b.vy>0);assert(Math.abs(Math.hypot(b.vx,b.vy)-410)<1e-9);h.get().rooms[h.get().current].obstacles=[{x:160,y:100,w:20,h:120}];b.vx=410;b.vy=0;h.steerShot(b,.1);assert.equal(b.vy,0);});
test('Explosions, chains and timed sticky charges deal bounded secondary damage without hurting players',()=>{for(let effect of ['explosive','chain','sticky']){let h=startSolo('rook');h.goFloor(1);let boss=h.get().boss;boss.x=200;boss.y=100;boss.hp=100;let other={id:999,x:230,y:100,r:17,hp:10};h.get().enemies.push(other);let hp=h.get().player.hp;h.hitEnemy(boss,{damage:2,vx:100,vy:0,[effect]:true,ownerSlot:1});if(effect==='explosive'){assert.equal(other.hp,8.6);assert.equal(boss.hp,98);}if(effect==='chain')assert.equal(other.hp,9);if(effect==='sticky'){assert.equal(boss.charges.length,1);h.specialStatusStep(.4);assert.equal(boss.hp,98);h.specialStatusStep(.41);assert(Math.abs(boss.hp-96.4)<1e-9);assert.equal(boss.charges.length,0);assert(Math.abs(other.hp-8.4)<1e-9);}assert.equal(h.get().player.hp,hp);}});
test('Poison, splitting, execution and critical shots have real combat effects',()=>{let h=startSolo('rook');h.goFloor(1);let boss=h.get().boss;boss.hp=100;h.hitEnemy(boss,{damage:1,poison:true});h.specialStatusStep(1);assert.equal(boss.hp,98);h.specialStatusStep(2);assert.equal(boss.hp,96);h.hitEnemy(boss,{damage:2,split:true,vx:100,vy:0});assert.equal(h.get().shots.length,2);assert(h.get().shots.every(b=>b.secondary&&!b.split&&b.hit.has(boss.id)));boss.hp=10;h.hitEnemy(boss,{damage:2,execute:true});assert.equal(boss.hp,7);h.take(h.items.find(i=>i.id==='critical'));let random=Math.random;try{Math.random=()=>0;h.shoot(0);assert.equal(h.get().shots.at(-1).damage,2);}finally{Math.random=random;}});
test('Foil shield blocks one hit, recharges per encounter and is not retained next run',()=>{let h=startSolo('rook'),p=h.get().player;h.take(h.items.find(i=>i.id==='shield'));h.unprotect();h.damagePlayer();assert.equal(p.hp,3);assert.equal(p.foilReady,false);h.unprotect();h.damagePlayer();assert.equal(p.hp,2);h.enterRoom(h.get().rooms.find(r=>r.kind==='battle').id);assert.equal(p.foilReady,true);h.newRun();assert.equal(p.foilReady,false);});
test('Vampiric kills heal only projectile owner even with identical co-op characters',()=>{let {h}=onlinePair(),a=h.get().player,b=h.get().partner;a.hp=1;b.hp=1;let enemy={id:999,x:100,y:100,r:17,hp:1},random=Math.random;try{Math.random=()=>0;h.hitEnemy(enemy,{damage:2,vampire:true,ownerSlot:2});assert.equal(a.hp,1);assert.equal(b.hp,2);h.hitEnemy(enemy,{damage:2,vampire:true,ownerSlot:2});assert.equal(b.hp,2);}finally{Math.random=random;}});
test('All rare effects render and synchronize through full and compact co-op snapshots',()=>{let {h,g}=onlinePair();for(let row of h.newItems)h.take(h.items.find(i=>i.id===row[0]),h.get().partner);h.goFloor(3);h.shoot(0,h.get().partner);for(let i=0;i<25;i++)h.tick();h.goFloor(6);h.shoot(0,h.get().partner);let full=h.makeNetworkSnapshot();assert(full.rooms);g.applyNetworkSnapshot(JSON.parse(JSON.stringify(full)));assert.equal(g.gear(g.get().partner).special.homing,true);assert.equal(g.gear(g.get().partner).special.explosive,true);assert.equal(g.get().shots.length,h.get().shots.length);assert(g.get().shots.every(s=>s.homing&&s.explosive&&s.sticky));let compact=h.makeNetworkSnapshot();assert.equal(compact.rooms,undefined);g.applyNetworkSnapshot(JSON.parse(JSON.stringify(compact)));assert.equal(g.gear(g.get().partner).special.sticky,true);assert.equal(g.get().partner.inventory.build.length,20);g.tick(5);assert.equal(g.get().state,h.get().state);assert(Buffer.byteLength(JSON.stringify(full))<262144);});


test('Utility and directional new recipes change projectile geometry and stats',()=>{let h=startSolo('rook'),p=h.get().player;for(let id of ['range','velocity','large','rear','diagonal','ice','garlic','timer'])h.take(h.items.find(i=>i.id===id));h.shoot(0);assert.equal(h.get().shots.length,4);let shot=h.get().shots[0];assert.equal(shot.life,3.22);assert.equal(shot.r,9);assert.equal(shot.chill,true);assert(Math.abs(Math.hypot(shot.vx,shot.vy)-512.5)<1e-9);assert.equal(shot.damage,1.5);assert.equal(h.shotRate(p),1.15);assert(h.get().shots.some(b=>b.vy>0));assert(h.get().shots.some(b=>b.vx>0));assert(h.get().shots.some(b=>b.vx<0));});
test('Knockback moves regular enemies but not bosses; sticky charge cap is bounded',()=>{let h=startSolo('rook');h.goFloor(1);let boss=h.get().boss;boss.x=200;boss.y=100;let x=boss.x;h.hitEnemy(boss,{damage:.1,knockback:true,vx:100,vy:0});assert.equal(boss.x,x);let enemy={id:999,x:200,y:200,r:17,hp:100};h.get().enemies.push(enemy);h.hitEnemy(enemy,{damage:1,knockback:true,vx:100,vy:0});assert.equal(enemy.x,218);for(let n=0;n<10;n++)h.hitEnemy(enemy,{damage:.1,sticky:true});assert.equal(enemy.charges.length,4);});
